import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { test } from 'vitest';
import { activateCard, createGame, isWon, MISMATCH_MS, MOVES_MAX } from '../game.ts';
import { boardCode } from '../deck.ts';
import {
  activateSession,
  initialSession,
  replaceGame,
  tickSession,
  SessionNotice,
} from './session.ts';
import { EXAMPLE_CODE, EXAMPLE_PAIRS } from '../game.fixture.ts';

const EMPTY_PREFERENCES = { size: 4, bestMoves: {} };

test('session generation rejects earlier callbacks after replacing a game', () => {
  const first = activateSession(
    activateSession(initialSession(EXAMPLE_CODE, EMPTY_PREFERENCES), 0),
    1,
  );
  const restarted = replaceGame(first, createGame(EXAMPLE_CODE), false);
  assert.equal(tickSession(restarted, first.generation, MISMATCH_MS), restarted);
  assert.equal(restarted.game.moves, 0);
  assert.equal(restarted.game.started, false);
  const active = activateSession(restarted, 2);
  assert.equal(tickSession(active, first.generation, MISMATCH_MS), active);
  const changed = replaceGame(first, createGame(boardCode(6, 1)), false);
  assert.equal(changed.preferences.size, 6);
});

test('an imported session blocks input and active time until Resume', () => {
  const first = activateSession(
    activateSession(initialSession(EXAMPLE_CODE, EMPTY_PREFERENCES), 0),
    1,
  );
  const paused = replaceGame(first, first.game, true);
  assert.equal(paused.feedback, SessionNotice.loaded);
  assert.equal(paused.loadNotice, paused.feedback);
  assert.equal(paused.announcement, first.announcement + 1);
  assert.equal(activateSession(paused, 2), paused);
  assert.equal(tickSession(paused, paused.generation, MISMATCH_MS), paused);
  assert.equal(paused.celebration, false);
  const pausedOne = replaceGame(paused, activateCard(createGame(EXAMPLE_CODE), 0), true);
  assert.equal(activateSession(pausedOne, 2), pausedOne, 'C10 paused import blocks activation');
  const resumed = { ...paused, paused: false };
  assert.notEqual(
    tickSession(resumed, resumed.generation, MISMATCH_MS).game.selection.kind,
    first.game.selection.kind,
  );
});

test('turn announcements happen once and repeat identical results as separate events', () => {
  const initial = initialSession(EXAMPLE_CODE, EMPTY_PREFERENCES);
  const first = activateSession(initial, 0);
  assert.equal(first.announcement, initial.announcement);
  const mismatch = activateSession(first, 1);
  assert.equal(mismatch.announcement, initial.announcement + 1);
  const closed = tickSession(mismatch, mismatch.generation, MISMATCH_MS);
  assert.equal(closed.announcement, mismatch.announcement);
  assert.equal(closed.feedback, mismatch.feedback);
  const repeated = activateSession(activateSession(closed, 0), 1);
  assert.equal(repeated.feedback, mismatch.feedback);
  assert.equal(repeated.announcement, mismatch.announcement + 1);
});

test('a new completion records bests but completed imports never do', () => {
  let session = initialSession(EXAMPLE_CODE, EMPTY_PREFERENCES);
  for (const pair of EXAMPLE_PAIRS)
    for (const index of pair) session = activateSession(session, index);
  assert.equal(isWon(session.game), true);
  assert.equal(session.preferences.bestMoves['4'], EXAMPLE_PAIRS.length);
  assert.equal(session.celebration, true);
  assert.equal(session.announcement, EXAMPLE_PAIRS.length);
  const imported = replaceGame(initialSession(EXAMPLE_CODE, EMPTY_PREFERENCES), session.game, true);
  assert.equal(imported.paused, false);
  assert.equal(imported.feedback, SessionNotice.loadedCompleted);
  assert.equal(imported.loadNotice, SessionNotice.loadedCompleted);
  assert.equal(imported.announcement, 1);
  assert.equal(imported.celebration, false);
  assert.equal(tickSession(imported, imported.generation, MISMATCH_MS), imported);
  assert.deepEqual(imported.preferences.bestMoves, {});
  assert.deepEqual(activateSession({ ...imported, paused: false }, 0).preferences.bestMoves, {});
  const pending = {
    ...session.game,
    matched: EXAMPLE_PAIRS.slice(0, -1).flat(),
    moves: EXAMPLE_PAIRS.length - 1,
  };
  let restored = { ...replaceGame(imported, pending, true), paused: false };
  for (const index of EXAMPLE_PAIRS[EXAMPLE_PAIRS.length - 1] ?? [])
    restored = activateSession(restored, index);
  assert.equal(restored.preferences.bestMoves['4'], EXAMPLE_PAIRS.length);
});

test('an imported game at the move cap records the capped count as its best', () => {
  const game = { ...createGame(EXAMPLE_CODE), started: true, moves: MOVES_MAX };
  const imported = replaceGame(initialSession(EXAMPLE_CODE, EMPTY_PREFERENCES), game, true);
  let session = { ...imported, paused: false };
  for (const pair of EXAMPLE_PAIRS)
    for (const index of pair) session = activateSession(session, index);
  assert.equal(session.preferences.bestMoves['4'], MOVES_MAX);
});

test('turn feedback matches the reviewed message snapshot', async () => {
  const initial = initialSession(EXAMPLE_CODE, EMPTY_PREFERENCES);
  const mismatch = activateSession(activateSession(initial, 0), 1);
  const matched = activateSession(activateSession(initial, 2), 6);
  let won = initial;
  for (const pair of EXAMPLE_PAIRS) for (const index of pair) won = activateSession(won, index);
  const expected: unknown = JSON.parse(
    await readFile(new URL('./session.feedback.fixture.json', import.meta.url), 'utf8'),
  );
  assert.deepEqual(
    {
      initial: initial.feedback,
      mismatch: mismatch.feedback,
      matched: matched.feedback,
      won: won.feedback,
    },
    expected,
  );
});
import assert from 'node:assert/strict';
import { test } from 'vitest';
import {
  DEFAULT_SIZE,
  PREFERENCES_KEY,
  PREFERENCES_VERSION,
  readPreferences,
  rememberBest,
  writePreferences,
} from './storage.ts';
import { MOVES_MAX } from '../game.ts';
import { SPEC_VECTOR } from '../game.fixture.ts';
import type { PreferenceStore } from './storage.ts';

function memoryStore(initial = ''): PreferenceStore {
  const entries = new Map([[PREFERENCES_KEY, initial]]);
  return {
    getItem: (key) => entries.get(key) ?? null,
    setItem: (key, value) => {
      entries.set(key, value);
    },
  };
}

test('preferences round trip size and separate minimum moves per size', () => {
  const store = memoryStore();
  const preferences = rememberBest(rememberBest({ size: 6, bestMoves: {} }, 4, 12), 6, 20);
  writePreferences(store, preferences);
  assert.deepEqual(readPreferences(store), preferences, 'R10 scores survive storage round trip');
  assert.equal(rememberBest(preferences, 4, 13), preferences, 'R10 worse score keeps best');
  assert.equal(rememberBest(preferences, 4, 12), preferences);
  assert.equal(rememberBest(preferences, 4, 9).bestMoves['4'], 9, 'R10 better score replaces best');
  assert.equal(preferences.bestMoves['6'], 20, 'R10 size six has its separate best');
});

test('a best at the move cap round trips and a larger saved best is ignored', () => {
  const store = memoryStore();
  const capped = { size: DEFAULT_SIZE, bestMoves: { [DEFAULT_SIZE]: MOVES_MAX } };
  writePreferences(store, capped);
  assert.deepEqual(readPreferences(store), capped);
  assert.equal(rememberBest(capped, DEFAULT_SIZE, MOVES_MAX), capped);
  const larger = {
    schemaVersion: PREFERENCES_VERSION,
    size: DEFAULT_SIZE,
    bestMoves: { [DEFAULT_SIZE]: MOVES_MAX + 1 },
  };
  store.setItem(PREFERENCES_KEY, JSON.stringify(larger));
  assert.deepEqual(readPreferences(store), { size: DEFAULT_SIZE, bestMoves: {} });
});

const INVALID_PREFERENCES = [
  '{',
  'null',
  '{}',
  JSON.stringify({ schemaVersion: PREFERENCES_VERSION, size: 5, bestMoves: {} }),
  JSON.stringify({ schemaVersion: PREFERENCES_VERSION, size: 6, bestMoves: { 4: 1 } }),
  JSON.stringify({ schemaVersion: PREFERENCES_VERSION, size: 6, bestMoves: { 4: -1 } }),
  JSON.stringify({ schemaVersion: PREFERENCES_VERSION, size: 6, bestMoves: { 4: 8.5 } }),
  JSON.stringify({ schemaVersion: PREFERENCES_VERSION, size: 6, bestMoves: { '04': 8 } }),
];
for (const [index, text] of INVALID_PREFERENCES.entries()) {
  test(`preferences ignore invalid saved data ${index + 1}`, () => {
    assert.deepEqual(readPreferences(memoryStore(text)), { size: DEFAULT_SIZE, bestMoves: {} });
  });
}

test('storage failures keep play available and never change unrelated keys', () => {
  const denied: PreferenceStore = {
    getItem: () => {
      throw new Error();
    },
    setItem: () => {
      throw new Error();
    },
  };
  assert.equal(DEFAULT_SIZE, SPEC_VECTOR.sizes[0]);
  assert.equal(readPreferences(denied).size, DEFAULT_SIZE);
  assert.doesNotThrow(() => writePreferences(denied, { size: DEFAULT_SIZE, bestMoves: {} }));
  assert.equal(readPreferences(null).size, DEFAULT_SIZE);
  const store = memoryStore();
  const unrelated = 'another-application';
  store.setItem(unrelated, 'kept');
  writePreferences(store, { size: DEFAULT_SIZE, bestMoves: {} });
  assert.equal(store.getItem(unrelated), 'kept');
});

import { expect, test } from './browser-test.ts';
import { EXAMPLE_CODE, EXAMPLE_PAIRS } from '../src/game/game.fixture.ts';
import { ReproductionControl } from '../src/game/controls/control-labels.ts';
import { SelectionKind } from '../src/game/selection.ts';
import { SNAPSHOT_VERSION } from '../src/game/snapshot.ts';
import { exportedSnapshot, loadTimedBoard } from './game-fixture.ts';
import { uiSnapshot } from './ui-snapshot.ts';

const REMAINING_MS = 300;

async function loadDraft(
  page: Parameters<typeof loadTimedBoard>[0],
  snapshot: unknown,
): Promise<void> {
  await page.locator('summary').click();
  await page
    .getByLabel(ReproductionControl.snapshot, { exact: true })
    .fill(JSON.stringify(snapshot));
  await page.getByRole('button', { name: ReproductionControl.loadSnapshot, exact: true }).click();
  await page.locator('summary').click();
}

test('Resume focuses the remembered card before removal and continues the exact remaining interval', async ({
  page,
}) => {
  await loadTimedBoard(page);
  const snapshot = {
    version: SNAPSHOT_VERSION,
    boardCode: EXAMPLE_CODE,
    matched: [],
    moves: 1,
    elapsedMs: 500,
    started: true,
    selection: { kind: SelectionKind.mismatch, first: 0, second: 1, remainingMs: REMAINING_MS },
  };
  await loadDraft(page, snapshot);
  await page.locator('.card').nth(2).click();
  await page.keyboard.press('Enter');
  await page.keyboard.press('ArrowRight');
  await expect(page.locator('.card').nth(3)).toBeFocused();
  await page.clock.runFor(2000);
  await expect(page.locator('.card.revealed')).toHaveCount(2);
  expect((await exportedSnapshot(page)).elapsedMs).toBe(snapshot.elapsedMs);
  await page.getByRole('button', { name: ReproductionControl.resume, exact: true }).click();
  await expect(page.locator('.card').nth(3)).toBeFocused();
  await page.clock.runFor(REMAINING_MS - 1);
  await expect(page.locator('.card.revealed')).toHaveCount(2);
  await page.clock.runFor(1);
  await expect(page.locator('.card.closed')).toHaveCount(16);
});

test('invalid drafts keep the current game and a loaded win changes neither best nor celebration', async ({
  page,
}) => {
  await loadTimedBoard(page);
  await page.locator('.card').nth(2).click();
  await page.locator('.card').nth(6).click();
  await page.locator('.card').nth(0).click();
  await page.clock.runFor(1200);
  const original = await exportedSnapshot(page);
  await page.locator('summary').click();
  const code = page.getByLabel(ReproductionControl.board, { exact: true });
  const invalidCode = 'invalid';
  await code.fill(invalidCode);
  await page.getByRole('button', { name: ReproductionControl.loadBoard, exact: true }).click();
  expect(await code.inputValue()).toBe(invalidCode);
  const field = page.getByLabel(ReproductionControl.snapshot, { exact: true });
  const invalidSnapshot = '{';
  await field.fill(invalidSnapshot);
  await page.getByRole('button', { name: ReproductionControl.loadSnapshot, exact: true }).click();
  expect(await field.inputValue()).toBe(invalidSnapshot);
  await page.locator('summary').click();
  expect(await exportedSnapshot(page)).toEqual(original);
  await loadDraft(page, {
    version: SNAPSHOT_VERSION,
    boardCode: EXAMPLE_CODE,
    matched: EXAMPLE_PAIRS.flat(),
    selection: { kind: SelectionKind.closed },
    moves: EXAMPLE_PAIRS.length,
    elapsedMs: 500,
    started: true,
  });
  await expect(page.locator('.card.matched')).toHaveCount(16);
  expect(await page.locator('.victory.celebrate').count()).toBe(0);
  const expected = await uiSnapshot();
  await expect(page.locator('.stats dd').nth(3)).toHaveText(expected.bestNone);
  await expect(
    page.getByRole('button', { name: ReproductionControl.resume, exact: true }),
  ).toHaveCount(0);
  await expect(page.getByRole('status')).toHaveText('Loaded completed snapshot.');
  await page.clock.runFor(1000);
  expect((await exportedSnapshot(page)).elapsedMs).toBe(500);
  await expect(page.locator('.card.matched')).toHaveCount(16);
  expect(await page.locator('.victory.celebrate').count()).toBe(0);
});
