import { EXAMPLE_CODE, EXAMPLE_PAIRS, SPEC_VECTOR } from './game.fixture.ts';

function snapshot(overrides: Record<string, unknown> = {}): string {
  return JSON.stringify({
    version: SNAPSHOT_VERSION,
    boardCode: EXAMPLE_CODE,
    matched: [],
    selection: { kind: SelectionKind.closed },
    moves: 0,
    elapsedMs: 0,
    started: false,
    ...overrides,
  });
}

test('snapshot round trips preserve pending time and serialize only the declared fields', () => {
  const state = advanceGame(activateCard(activateCard(createGame(EXAMPLE_CODE), 0), 1), 175);
  assert.deepEqual(decodeSnapshot(encodeSnapshot(state)), state);
  assert.deepEqual(state.selection, {
    kind: SelectionKind.mismatch,
    first: 0,
    second: 1,
    remainingMs: MISMATCH_MS - 175,
  });
  assert.equal(SNAPSHOT_VERSION, SPEC_VECTOR.snapshotVersion);
  assert.equal(SNAPSHOT_MAX_BYTES, SPEC_VECTOR.snapshotBytes);
  const exported: unknown = JSON.parse(encodeSnapshot(state));
  assert.ok(exported && typeof exported === 'object');
  assert.deepEqual(Object.keys(exported).sort(), [...SNAPSHOT_KEYS].sort());
});

test('snapshot imports accept property order changes while keeping the exact key set', () => {
  const reordered = JSON.stringify({
    boardCode: EXAMPLE_CODE,
    matched: [],
    selection: { kind: SelectionKind.closed },
    moves: 0,
    elapsedMs: 0,
    started: false,
    version: SNAPSHOT_VERSION,
  });
  assert.ok(decodeSnapshot(reordered));
  const withExtra = JSON.stringify({
    version: SNAPSHOT_VERSION,
    boardCode: EXAMPLE_CODE,
    matched: [],
    selection: { kind: SelectionKind.closed },
    moves: 0,
    elapsedMs: 0,
    started: false,
    extra: true,
  });
  assert.equal(decodeSnapshot(withExtra), null);
});

test('named snapshots round trip their name and version 1 imports have no name', () => {
  const state = activateCard(createGame(EXAMPLE_CODE), 0);
  const name = '  Café 🃏  ';
  const text = encodeSnapshot(state, name);
  const exported: unknown = JSON.parse(text);
  if (!isJsonObject(exported)) throw new Error('Expected a snapshot object.');
  assert.deepEqual(Object.keys(exported).sort(), [...NAMED_SNAPSHOT_KEYS].sort());
  assert.equal(exported.version, NAMED_SNAPSHOT_VERSION);
  assert.equal(exported.name, name);
  assert.deepEqual(decodeSnapshotData(text), { game: state, name });
  assert.equal(decodeSnapshotData(snapshot())?.name, '');
});

test('deal names follow the 40 UTF-16 code unit and line break rules', () => {
  assert.equal(isValidDealName(''), true);
  assert.equal(isValidDealName('  kept  '), true);
  assert.equal(isValidDealName('🃏'.repeat(20)), true);
  assert.equal(isValidDealName('🃏'.repeat(21)), false);
  for (const name of ['', 'x'.repeat(41), 'bad\rname', 'bad\nname']) {
    assert.equal(decodeSnapshotData(snapshot({ version: 2, name })), null);
  }
});

test('snapshots accept whole pairs and completed states without changing the source order', () => {
  const state = activateCard(activateCard(createGame(EXAMPLE_CODE), 6), 2);
  assert.deepEqual(decodeSnapshot(encodeSnapshot(state))?.matched, [2, 6]);
  assert.deepEqual(state.matched, [6, 2]);
  assert.equal(
    decodeSnapshot(
      snapshot({ matched: EXAMPLE_PAIRS.flat(), moves: EXAMPLE_PAIRS.length, started: true }),
    )?.matched.length,
    16,
  );
  assert.ok(decodeSnapshot(snapshot({ moves: 17, started: true })));
});

