 43	export function encodeSnapshot(state: GameState, name = ''): string {
 44	  const fields = {
 45	    boardCode: state.boardCode,
 46	    matched: [...state.matched].sort((left, right) => left - right),
 47	    // Active time keeps its fractions in play. Export writes whole milliseconds, and rounding
 48	    // pending time up keeps a mismatch at 1ms or more.
 49	    selection:
 50	      state.selection.kind === SelectionKind.mismatch
 51	        ? { ...state.selection, remainingMs: Math.ceil(state.selection.remainingMs) }
 52	        : state.selection,
 53	    moves: state.moves,
 54	    elapsedMs: Math.floor(state.elapsedMs),
 55	    started: state.started,
 56	  };
 57	  const value =
 58	    name.length > 0 && isValidDealName(name)
 59	      ? { version: NAMED_SNAPSHOT_VERSION, name, ...fields }
 60	      : { version: SNAPSHOT_VERSION, ...fields };
 61	  return JSON.stringify(value, null, 2);
 62	}
