 64	export function decodeSnapshotData(text: string): DecodedSnapshot | null {
 65	  const value = isWithinBytes(text, SNAPSHOT_MAX_BYTES) ? parseJson(text) : undefined;
 66	  if (!isJsonObject(value)) return null;
 67	  const named = value.version === NAMED_SNAPSHOT_VERSION;
 68	  if (value.version !== SNAPSHOT_VERSION && !named) return null;
 69	  const keys = named ? NAMED_SNAPSHOT_KEYS : SNAPSHOT_KEYS;
 70	  if (!hasExactKeys(value, keys)) return null;
 71	  let name = '';
 72	  if (named) {
 73	    if (!isValidDealName(value.name) || value.name.length === 0) return null;
 74	    name = value.name;
 75	  }
 76	  if (typeof value.boardCode !== 'string' || !parseBoardCode(value.boardCode)) return null;
 77	  if (
 78	    !isNonnegativeSafeInteger(value.moves) ||
 79	    value.moves > MOVES_MAX ||
 80	    !isNonnegativeSafeInteger(value.elapsedMs) ||
 81	    value.elapsedMs > ELAPSED_MAX_MS ||
 82	    typeof value.started !== 'boolean'
 83	  )
