 85	  const initial = createGame(value.boardCode);
 86	  const matched = readMatched(value.matched, initial);
 87	  if (!matched) return null;
 88	  const selection = readSelection(value.selection, initial, matched);
 89	  if (!selection) return null;
 90	  const state: GameState = {
 91	    ...initial,
 92	    matched,
 93	    selection,
 94	    moves: value.moves,
 95	    elapsedMs: value.elapsedMs,
 96	    started: value.started,
 97	  };
 98	  const minimumMoves = matched.length / 2 + (selection.kind === SelectionKind.mismatch ? 1 : 0);
 99	  if (state.moves < minimumMoves) return null;
100	  if (
101	    !state.started &&
102	    (state.moves !== 0 ||
103	      state.elapsedMs !== 0 ||
104	      matched.length !== 0 ||
105	      selection.kind !== SelectionKind.closed)
106	  )
107	    return null;
108	  if (state.started && state.moves === 0 && selection.kind === SelectionKind.closed) return null;
