 41	export function replaceGame(
 42	  session: Session,
 43	  game: GameState,
 44	  imported: boolean,
 45	  name = '',
 46	): Session {
 47	  const paused = imported && !isWon(game);
 48	  const loadNotice = imported
 49	    ? paused
 50	      ? SessionNotice.loaded
 51	      : SessionNotice.loadedCompleted
 52	    : '';
 53	  return {
 54	    ...session,
 55	    game,
 56	    name: imported ? name : '',
 57	    paused,
 58	    generation: session.generation + 1,
 59	    celebration: false,
 60	    preferences: { ...session.preferences, size: game.size },
 61	    // Only loads have a published status. A new deal clears the last turn result silently.
 62	    announcement: imported ? session.announcement + 1 : session.announcement,
 63	    feedback: loadNotice,
 64	    loadNotice,
 65	  };
 66	}
