 68	export function tickSession(session: Session, generation: number, milliseconds: number): Session {
 69	  if (session.generation !== generation || session.paused) return session;
 70	  const game = advanceGame(session.game, milliseconds);
 71	  return game === session.game ? session : { ...session, game };
 72	}

